def submit(self, request, actor):
    required = {'project', 'branch', 'commit', 'environment', 'harbor', 'run_verify', 'request_id'}
    if set(request) != required or type(request['run_verify']) is not bool:
        raise ValueError('发布参数不完整，run_verify 必须为布尔值')
    selected = self.for_project(request['project'])
    for field in ('project', 'environment', 'harbor'):
        if request[field] != selected.config[field]['id']:
            raise ValueError('所选项目、环境或 Harbor 尚未接入')
    if not re.fullmatch(r'[0-9a-f]{40}', request['commit']) or not re.fullmatch(r'[a-zA-Z0-9-]{16,64}', request['request_id']):
        raise ValueError('无效的提交号或请求标识')
    signature = {k: v for k, v in request.items() if k != 'request_id'}
    with self.lock:
        for previous in self.jobs.values():
            if previous['request_id'] == request['request_id'] and previous['actor'] == actor:
                if previous['selection'] != signature:
                    raise ValueError('同一请求标识不能用于不同发布参数')
                return copy.deepcopy(previous)
        if any(j['status'] not in TERMINAL for j in self.jobs.values()):
            raise ValueError('已有发布任务执行中，请等待完成')
    branches = selected.branches()
    if not any(b['name'] == request['branch'] and b['sha'] == request['commit'] for b in branches):
        raise ValueError('远程分支已更新，请刷新分支后重新发布')
    with self.lock:
        if any(j['status'] not in TERMINAL for j in self.jobs.values()):
            raise ValueError('已有发布任务执行中，请等待完成')
        identity = uuid.uuid4().hex
        directory = self.jobs_dir / identity
        directory.mkdir(mode=0o700)
        catalog = next(p for p in self.catalog()['projects'] if p['id'] == request['project'])
        job = {'id': identity, 'request_id': request['request_id'], 'actor': actor, 'selection': signature,
               'project': request['project'], 'project_name': selected.config['project']['name'],
               'repository': selected.config['project']['repository'],
               'target': {'environment': catalog['environment'], 'harbor': catalog['harbor']},
               'status': 'queued', 'created_at': now(), 'steps': [
                   {'id': key, 'name': catalog['verify_label'] if key == 'verify' else name, 'status': 'pending'} for key, name in STAGES],
               'source_commit': request['commit'], 'branch': request['branch'],
               'run_verify': request['run_verify'], 'business_acceptance': 'NOT_RUN_NOT_IN_SCOPE',
               'environment': selected.config['environment']['name'], 'error': None}
        self.jobs[identity] = job
        self.save(job)
        self.queue.put(identity)
        return copy.deepcopy(job)
